            | Pattern::AttributeLiteralEnd
            | Pattern::EventScriptEnd
            | Pattern::EventScriptDoubleLineCommentEnd
            | Pattern::EventScriptSingleLineCommentEnd
            | Pattern::AttributesKeyvalueEnd
            | Pattern::KeyvalueEqualsEnd
            | Pattern::AttributesInterpolatedEnd
            | Pattern::LangJsonEnd
            | Pattern::LangModuleEnd
            | Pattern::LangNamedEnd
            | Pattern::TagsStartAttributesEnd
